1	import { Card } from "@/components/ui/Card";
2	import { ProviderApprovalCard } from "@/components/admin/ProviderApprovalCard";
3	import { PayoutRunner } from "@/components/admin/PayoutRunner";
4	import { requireRole } from "@/lib/auth";
5	import { listProvidersByStatus, listDecidedProviders } from "@/lib/db/queries";
6	import { getVoiceIntroSignedUrl } from "@/lib/storage";
7	import { t } from "@/lib/i18n";
8	import { type ProviderRow } from "@/lib/supabase/types";
9	
10	export const metadata = { title: `${t("admin.title")} · ${t("app.name")}` };
11	
12	async function withAudio(providers: ProviderRow[]) {
13	  return Promise.all(
14	    providers.map(async (provider) => ({
15	      provider,
16	      audioUrl: await getVoiceIntroSignedUrl(provider.voice_intro_path),
17	    })),
18	  );
19	}
