21	export default async function AdminProvidersPage() {
22	  await requireRole("admin");
23	  const [pending, decided] = await Promise.all([
24	    listProvidersByStatus("pending"),
25	    listDecidedProviders(),
26	  ]);
27	  const [pendingWithAudio, decidedWithAudio] = await Promise.all([
28	    withAudio(pending),
29	    withAudio(decided),
30	  ]);
31	
32	  return (
33	    <div className="flex flex-col gap-8">
34	      <div className="flex flex-col gap-1.5">
35	        <h1 className="text-h1">{t("admin.title")}</h1>
36	        <p className="text-lg text-ink-soft">{t("admin.subtitle")}</p>
37	      </div>
38	
39	      <PayoutRunner />
40	
41	      <section className="flex flex-col gap-4">
42	        <h2 className="text-h2">{t("admin.pendingHeading")}</h2>
43	        {pendingWithAudio.length === 0 ? (
44	          <Card>
45	            <p className="text-base text-ink-soft">{t("admin.pendingNone")}</p>
46	          </Card>
47	        ) : (
48	          <ul className="flex flex-col gap-4">
49	            {pendingWithAudio.map(({ provider, audioUrl }) => (
50	              <ProviderApprovalCard
51	                key={provider.id}
52	                provider={provider}
53	                audioUrl={audioUrl}
54	              />
55	            ))}
56	          </ul>
57	        )}
58	      </section>
59	
60	      <section className="flex flex-col gap-4">
61	        <h2 className="text-h2">{t("admin.otherHeading")}</h2>
62	        {decidedWithAudio.length === 0 ? (
63	          <Card>
64	            <p className="text-base text-ink-soft">{t("admin.otherNone")}</p>
65	          </Card>
66	        ) : (
67	          <ul className="flex flex-col gap-4">
68	            {decidedWithAudio.map(({ provider, audioUrl }) => (
69	              <ProviderApprovalCard
70	                key={provider.id}
71	                provider={provider}
72	                audioUrl={audioUrl}
73	              />
74	            ))}
75	          </ul>
76	        )}
77	      </section>
78	    </div>
79	  );
80	}
