1	import * as React from "react";
2	
3	/**
4	 * Shared dashboard page header — a consistent landmark heading + lead used by
5	 * the listener, customer, and admin dashboards. The role-aware nav, the page
6	 * `<main>` landmark, and the persistent safety link come from the route-group
7	 * layouts and the root layout.
8	 */
9	export function DashboardHeader({
10	  title,
11	  description,
12	  action,
13	}: {
14	  title: string;
15	  description?: string;
16	  action?: React.ReactNode;
17	}) {
18	  return (
19	    <div className="flex flex-wrap items-start justify-between gap-3">
20	      <div className="flex flex-col gap-1.5">
21	        <h1 className="text-h1">{title}</h1>
22	        {description ? (
23	          <p className="text-lg text-ink-soft">{description}</p>
24	        ) : null}
25	      </div>
26	      {action ? <div className="flex items-center gap-3">{action}</div> : null}
27	    </div>
28	  );
29	}
