1	import { Suspense } from "react";
2	import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
3	import { AdminUserSearch } from "@/components/admin/AdminUserSearch";
4	import { UsersTable } from "@/components/admin/UsersTable";
5	import { requireRole } from "@/lib/auth";
6	import { listUsers } from "@/lib/db/queries";
7	import { t } from "@/lib/i18n";
8	
9	export const metadata = { title: `${t("admin.usersTitle")} · ${t("app.name")}` };
10	
11	export default async function AdminUsersPage({
12	  searchParams,
13	}: {
14	  searchParams: Promise<{ q?: string }>;
15	}) {
16	  await requireRole("admin");
17	  const { q } = await searchParams;
18	  const users = await listUsers(q);
19	
20	  return (
21	    <div className="flex flex-col gap-6">
22	      <DashboardHeader
23	        title={t("admin.usersTitle")}
24	        description={t("admin.usersSubtitle")}
25	      />
26	      <Suspense fallback={null}>
27	        <AdminUserSearch />
28	      </Suspense>
29	      <p className="text-base font-bold text-ink-soft" aria-live="polite">
30	        {t("admin.usersResultsCount", { count: users.length })}
31	      </p>
32	      <UsersTable
33	        rows={users.map((u) => ({
34	          id: u.id,
35	          name: u.full_name || "—",
36	          email: u.email,
37	          role: u.role,
38	          suspended: u.is_suspended,
39	        }))}
40	      />
41	    </div>
42	  );
43	}
